<main class="content container-fluid teacher-home"><section class="teacher-hero mb-4"><div><span class="eyebrow">ESPACIO DOCENTE</span><h2>Hola, <?=e($user['first_name'])?>.</h2><p>Todo lo que necesitas para avanzar en tu ruta docente, organizado en un solo lugar.</p></div><div class="teacher-identity"><span class="subject-label">TU ASIGNATURA</span><strong><?=e($user['subject']??'General')?></strong><a href="<?=url('/docente/perfil')?>">Ver mi perfil →</a><a class="panel-manual-link" href="<?=url("/assets/docs/manual-docente-ruta-docente.pdf")?>" download><span>↓</span><span><b>Descargar manual</b><small>Guía para docentes · PDF</small></span></a></div></section><div class="teacher-overview mb-4"><div><span class="overview-icon purple">✓</span><p><strong><?=count($tests)?></strong><span>Tests disponibles</span></p></div><div><span class="overview-icon blue">▦</span><p><strong><?=count($tabulators)?></strong><span>Talleres asincrónicos</span></p></div><div class="overview-message"><span>Actualizado</span><p>Accede a tus recursos asignados y continúa tu preparación.</p></div></div><?php foreach([['Tests disponibles',$tests,$user['test_enabled'],'test','Evaluaciones y actividades asociadas a tu asignatura.'],['Talleres asincrónicos',$tabulators,$user['tabulator_enabled'],'tabulador','Herramientas para organizar y analizar tus resultados.']] as [$label,$items,$enabled,$type,$description]):?><section class="teacher-module mb-4"><div class="module-heading"><div><span class="module-kicker"><?=$type==='test'?'EVALUACIÓN':'ANÁLISIS'?></span><h2><?=$label?></h2><p><?=e($description)?></p></div><div class="module-heading-actions"><span class="resource-count"><?=count($items)?> <?=count($items)===1?'recurso':'recursos'?></span><a href="<?=url($type==='test'?'/docente/tests':'/docente/talleres-asincronicos')?>">Ver módulo →</a></div></div><?php if(!$enabled):?><div class="empty-state compact-empty">Este módulo aún no está habilitado en tu perfil.</div><?php elseif(!$items):?><div class="empty-state compact-empty">No hay recursos publicados para tu asignatura.</div><?php else:?><div class="teacher-resource-list"><?php foreach($items as $r):?><article class="teacher-resource-item"><span class="resource-icon <?=$type==='tabulador'?'tabulator-icon':''?>"><?=$type==='test'?'✓':'▦'?></span><div class="resource-copy"><span class="resource-meta"><?=e(strtoupper($type))?></span><h3><?=e($r['name'])?></h3><p><?=e($r['description']?:'Recurso disponible para tu preparación docente.')?></p></div><div class="resource-actions"><?php if($r['file_path']):?><a class="btn btn-brand btn-sm" href="<?=url('/docente/descargar?id='.$r['id'])?>">Descargar <span>↓</span></a><?php endif;?><?php if($r['external_link']):?><a class="btn btn-outline-primary btn-sm" href="<?=e($r['external_link'])?>" target="_blank" rel="noopener noreferrer"><?=$type==='test'?'Acceder al test':'Acceder al taller'?> <span>↗</span></a><?php endif;?></div></article><?php endforeach;?></div><?php endif;?></section><?php endforeach;?></main>
